function getInternalLinks(html, baseDomain, limit = 5) {
    const links = new Set();

    // Normalize base domain
    baseDomain = baseDomain.replace(/\/+$/, "");

    // Always include homepage
    links.add(baseDomain + "/");

    const regex = /<a\b[^>]*href\s*=\s*(['"])(.*?)\1/gi;
    let match;

    while ((match = regex.exec(html)) !== null) {
        if (links.size >= limit) break;

        let href = match[2].trim();

        if (!href) continue;

        // Ignore unwanted links
        if (/^(#|mailto:|tel:|javascript:|sms:)/i.test(href)) continue;
        if (/\.(jpg|jpeg|png|gif|svg|webp|ico|pdf|zip|css|js|mp4|mp3)(\?|$)/i.test(href)) continue;

        let absolute;

        if (/^https?:\/\//i.test(href)) {
            absolute = href;
        } else if (href.startsWith("//")) {
            absolute = "https:" + href;
        } else if (href.startsWith("/")) {
            absolute = baseDomain + href;
        } else {
            absolute = baseDomain + "/" + href;
        }

        // Remove query/hash
        absolute = absolute.split("#")[0].split("?")[0];

        // Remove trailing slash except homepage
        if (
            absolute.endsWith("/") &&
            absolute !== baseDomain + "/"
        ) {
            absolute = absolute.slice(0, -1);
        }

        // Keep only internal links
        if (
            absolute === baseDomain ||
            absolute.startsWith(baseDomain + "/")
        ) {
            links.add(absolute);
        }
    }

    return Array.from(links).slice(0, limit);
}

